using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using TMPro;using CrossTheLine;using CrossTheLine.EditorTools;
public static class FontLifecycleRegression {
 public static string Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");JourneyEditorFontPreview.Refresh();var korean=JourneyRuntimeFonts.SystemKorean;if(!JourneyRuntimeFonts.IsUsable(korean))throw new Exception("Dead system font atlas");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var g=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<JourneyGame>(true)).First();if(!g.koreanFont.HasCharacters("예수님 광야 세례 제자 새 여정 이어 걷기 설정",out uint[] missing,true,true))throw new Exception("Korean glyph fallback failed");int n=0;foreach(var root in scene.GetRootGameObjects())foreach(var text in root.GetComponentsInChildren<TMP_Text>(true)){text.ForceMeshUpdate(true);n++;}string result="PASS Edit-mode font refresh after Play exit: live fallback atlas, Korean glyph insertion, "+n+" scene text meshes rebuilt without destroyed-texture access.";File.WriteAllText("Docs/QA/RenderedChapters/FontLifecycle.txt",result);return result;}
}

